<script setup>
import {ref,computed,onMounted} from 'vue'
import {route} from '../router.js'
import {api,money,orderStates,payStates} from '../api/client.js'
import Pager from '../components/Pager.vue'
import Editor from '../components/Editor.vue'
import OrderDetail from '../components/OrderDetail.vue'
const tab=computed(()=>route.value.split('/')[2]),titles={dashboard:'工作台',orders:'订单管理',dish:'菜品管理',setmeal:'套餐管理',category:'分类管理',employee:'员工管理',reports:'数据统计'}
const rows=ref([]),total=ref(0),page=ref(1),loading=ref(false),busy=ref(false),name=ref(''),status=ref(''),phone=ref(''),shop=ref(0),stats=ref({}),detail=ref(null),editing=ref(null),notice=ref(''),reports=ref(null)
const date=d=>d.toLocaleDateString('en-CA'),end=ref(date(new Date())),begin=ref(date(new Date(Date.now()-6*86400000)))
const get=(path,params)=>api('admin','GET',path,undefined,params)
async function load(){loading.value=true;try{if(tab.value==='dashboard'){const [a,b]=await Promise.all([get('/workspace/businessData'),get('/shop/status')]);stats.value=a;shop.value=b}else if(tab.value==='reports'){const p={begin:begin.value,end:end.value};const [turnover,orders,users,top]=await Promise.all(['/turnoverStatistics','/ordersStatistics','/user','/top10'].map(s=>get('/report'+s,p)));reports.value={turnover,orders,users,top}}else{const p={page:page.value,pageSize:10,...(tab.value==='orders'?{number:name.value,phone:phone.value,status:status.value}:{name:name.value,...(['dish','setmeal'].includes(tab.value)?{status:status.value}:{})})};const data=await get(tab.value==='orders'?'/order/conditionSearch':'/'+tab.value+'/page',p);rows.value=data.records||[];total.value=data.total||0}}catch{}finally{loading.value=false}}
onMounted(load)
async function action(fn,message='操作成功'){if(busy.value)return false;busy.value=true;try{await fn();notice.value=message;await load();return true}catch{return false}finally{busy.value=false}}
async function edit(row){try{editing.value=row?(tab.value==='category'?{...row}:await get('/'+tab.value+'/'+row.id)):{} }catch{}}
async function remove(row){if(!confirm('确认删除「'+row.name+'」？'))return;await action(()=>api('admin','DELETE','/'+tab.value+(tab.value==='employee'?'/'+row.id:''),undefined,tab.value==='employee'?undefined:{id:row.id}))}
async function orderAction(row,kind){let body;if(kind==='rejection'){const reason=prompt('请输入拒单原因');if(!reason?.trim())return;body={id:row.id,rejectionReason:reason.trim()}}else if(kind==='confirm')body={id:row.id};await action(()=>api('admin','PUT','/order/'+kind+(['delivery','complete'].includes(kind)?'/'+row.id:''),body))}
async function view(row){try{detail.value=await get('/order/details/'+row.id)}catch{}}
async function saved(data){if(await action(()=>api('admin',data.id?'PUT':'POST','/'+tab.value,data),'保存成功'))editing.value=null}
</script>
<template>
<div class="page-title"><div><span class="eyebrow">BUSINESS CENTER</span><h1>{{titles[tab]}}</h1></div><button @click="load" :disabled="loading">↻ 刷新</button></div><p v-if="notice" class="success" role="status">{{notice}}</p><p v-if="loading" class="muted" role="status">正在加载最新数据…</p>
<template v-if="tab==='dashboard'"><section class="hero"><div><span class="badge">今日营业</span><h2>用心经营，美味常在。</h2><p>每一份订单，都是一份信任。</p></div><button class="primary" :disabled="busy" @click="action(()=>api('admin','PUT','/shop/status/'+(shop===1?0:1)))">{{shop===1?'营业中 · 点击打烊':'已打烊 · 点击营业'}}</button></section><div class="metrics"><article v-for="[k,t] in [['turnover','今日营业额'],['orderCount','订单总数'],['validOrderCount','有效订单'],['newUserCount','新增用户']]" :key="k" class="card"><p class="muted">{{t}}</p><strong>{{k==='turnover'?money(stats[k]):stats[k]??'—'}}</strong><small>今日实时数据</small></article></div><section class="card"><h2>订单待办</h2><div class="metrics"><a href="#/admin/orders" class="task"><b>{{stats.waitingOrders??'—'}}</b>待接单 →</a><a href="#/admin/orders" class="task"><b>{{stats.deliveryOrders??'—'}}</b>派送中 →</a></div></section></template>
<template v-else-if="tab==='reports'"><form class="toolbar" @submit.prevent="load"><label>开始日期<input type="date" v-model="begin" required :max="end"></label><label>结束日期<input type="date" v-model="end" required :min="begin"></label><button class="primary">查询</button></form><template v-if="reports"><div class="metrics"><article class="card"><p>订单总数</p><strong>{{reports.orders.totalOrderCount}}</strong></article><article class="card"><p>有效订单</p><strong>{{reports.orders.validOrderCount}}</strong></article><article class="card"><p>完成率</p><strong>{{(Number(reports.orders.orderCompletionRate||0)*100).toFixed(1)}}%</strong></article></div><section class="card"><h2>营业额趋势</h2><div class="chart"><div v-for="(value,i) in reports.turnover.turnoverList" :key="i" class="bar-item"><b>{{money(value)}}</b><div class="bar" :style="{height:Math.max(2,Number(value)/Math.max(1,...reports.turnover.turnoverList.map(Number))*150)+'px'}"></div><small>{{reports.turnover.dateList[i]}}</small></div></div></section><div class="report-grid"><section class="card"><h2>销量 TOP 10</h2><div class="line" v-for="(n,i) in reports.top.nameList" :key="i"><span>{{i+1}}. {{n}}</span><b>{{reports.top.numberList[i]}} 份</b></div><p v-if="!reports.top.nameList?.length" class="empty">暂无销量</p></section><section class="card"><h2>用户增长</h2><div class="line" v-for="(d,i) in reports.users.dateList" :key="d"><span>{{d}}</span><b>+{{reports.users.newUserList[i]}}</b></div></section></div></template></template>
<template v-else><form class="toolbar" @submit.prevent="page=1;load()"><input v-model="name" :placeholder="tab==='orders'?'搜索订单号':'搜索名称'" aria-label="搜索"><input v-if="tab==='orders'" v-model="phone" placeholder="手机号" aria-label="手机号"><select v-if="['orders','dish','setmeal'].includes(tab)" v-model="status" aria-label="筛选状态"><option value="">全部状态</option><template v-if="tab==='orders'"><option v-for="(s,i) in orderStates.slice(1)" :value="i+1" :key="i">{{s}}</option></template><template v-else><option :value="1">起售</option><option :value="0">停售</option></template></select><button class="primary">查询</button><button v-if="tab!=='orders'" type="button" class="primary push" @click="edit()">＋ 新增</button></form><section class="card table-wrap"><table><thead><tr><th>{{tab==='orders'?'订单号':'名称'}}</th><th>{{tab==='orders'?'收货信息':tab==='employee'?'账号':tab==='category'?'类型':'售价'}}</th><th>{{tab==='category'?'排序':'状态'}}</th><th>{{tab==='orders'?'下单时间':'编号'}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><img v-if="row.image" :src="row.image" class="thumb" alt="">{{tab==='orders'?row.number:row.name}}</td><td v-if="tab==='orders'">{{row.consignee}}<br><small>{{row.phone}}</small><br>{{money(row.amount)}}</td><td v-else>{{tab==='employee'?row.username:tab==='category'?(row.type===1?'菜品分类':'套餐分类'):money(row.price)}}</td><td><span class="badge">{{tab==='orders'?orderStates[row.status]:tab==='category'?row.sort:row.status===1?'已启用':'已停用'}}</span><small v-if="tab==='orders'"> {{payStates[row.payStatus]}}</small></td><td class="muted">{{tab==='orders'?row.orderTime:row.id}}</td><td><div class="actions"><template v-if="tab==='orders'"><button @click="view(row)">详情</button><button v-if="row.status===2" :disabled="busy" @click="orderAction(row,'confirm')">接单</button><button v-if="row.status===2" :disabled="busy" @click="orderAction(row,'rejection')">拒单</button><button v-if="row.status===3" :disabled="busy" @click="orderAction(row,'delivery')">派送</button><button v-if="row.status===4" :disabled="busy" @click="orderAction(row,'complete')">完成</button></template><template v-else><button @click="edit(row)">编辑</button><button v-if="tab!=='category'" :disabled="busy" @click="action(()=>api('admin','POST','/'+tab+'/status/'+(row.status===1?0:1),undefined,{id:row.id}))">{{row.status===1?'停用':'启用'}}</button><button class="danger" :disabled="busy" @click="remove(row)">删除</button></template></div></td></tr></tbody></table><p v-if="!loading&&!rows.length" class="empty">暂无数据，请调整筛选条件或新增记录</p><Pager :page="page" :total="total" :size="10" @change="p=>{page=p;load()}"/></section></template>
<Editor v-if="editing" :kind="tab" :value="editing" :busy="busy" @close="editing=null" @save="saved"/><OrderDetail v-if="detail" :order="detail" @close="detail=null"/>
</template>
